"""Verify the Maconomy invoice card requests generated by the V2 sync."""

import asyncio
import json
import uuid
from types import SimpleNamespace
from unittest.mock import AsyncMock

import httpx
import pytest

from app.features.sap_concur_invoice_integration_v2.services.maconomy_invoice_service import (
    MaconomyInvoiceService,
)


@pytest.fixture
def create_invoice(monkeypatch):
    settings = SimpleNamespace(
        maconomy_url="https://maconomy.example.test",
        maconomy_shortname="test",
    )
    service = MaconomyInvoiceService(settings=settings)
    monkeypatch.setattr(service, "_get_reconnect_token", AsyncMock(return_value="test"))
    monkeypatch.setattr(
        service, "get_all_vendor_numbers", AsyncMock(return_value={"v-1"})
    )
    monkeypatch.setattr(service, "get_all_entity_names", AsyncMock(return_value=set()))

    requests = {}
    token = str(uuid.uuid4())

    def respond(request):
        assert request.method == "POST"
        endpoint = request.url.path.rsplit("/", 1)[-1]
        requests[endpoint] = json.loads(request.content)
        responses = {
            "instances": {"meta": {"containerInstanceId": str(uuid.uuid4())}},
            "init": {},
            "card": {"journalnumber": "J-1", "linenumber": 1},
        }
        return httpx.Response(
            200,
            json=responses[endpoint],
            headers={"Maconomy-Concurrency-Control": token},
        )

    client = httpx.AsyncClient(transport=httpx.MockTransport(respond))
    monkeypatch.setattr(httpx, "AsyncClient", lambda **kwargs: client)

    def run(invoice_fields):
        invoice = {
            "Name": "Test invoice",
            "InvoiceNumber": "INV-1",
            "InvoiceDate": "2026-11-01",
            "VendorCode": "V-1",
            **invoice_fields,
        }
        [(result, _)] = asyncio.run(
            service.create_invoices([{"invoice": invoice, "lineItems": []}])
        )
        return result, requests

    return run


@pytest.mark.parametrize(
    ("invoice_fields", "entry_date", "invoice_id"),
    [
        (
            {"PaymentRequestId": " PR-1 ", "ID": "legacy", "PostingDate": "11/10/2026"},
            "2026-11-10",
            "PR-1",
        ),
        ({"ID": " PR-2 "}, None, "PR-2"),
        ({"PaymentRequestId": "PR-1", "PostingDate": None}, None, "PR-1"),
        ({"PaymentRequestId": "PR-1", "PostingDate": "  "}, None, "PR-1"),
    ],
)
def test_card_request_maps_dates_and_transaction_number(
    create_invoice, invoice_fields, entry_date, invoice_id
):
    result, requests = create_invoice(invoice_fields)

    assert result["status"] == "SUCCESS"
    card_fields = requests["instances"]["panes"]["card"]["fields"]
    assert {"automaticvoucher", "transactionnumber"} <= set(card_fields)

    data = requests["card"]["data"]
    assert data["automaticvoucher"] is False
    assert data["transactionnumber"] == data["remark5"] == invoice_id
    assert data["invoicedate"] == "2026-11-01"
    if entry_date is None:
        assert "entrydate" not in data
    else:
        assert data["entrydate"] == entry_date


def test_invalid_posting_date_fails_before_opening_maconomy_instance(create_invoice):
    result, requests = create_invoice(
        {"PaymentRequestId": "PR-1", "PostingDate": "invalid"}
    )

    assert result["status"] == "FAILED"
    assert "Unparseable PostingDate" in result["message"]
    assert requests == {}
